(2393785, 329854, 10985, '<td valign="top">Fantastic angle and expression. This should do very well!</td>', 'Fantastic angle and expression. This should do very well!', '2006-05-08 15:00:28.000000', NULL, 1),
(2393789, 329293, 10985, '<td valign="top">Good post-processing: half photo, half watercolor. Nicely contrasted and saturated, too.</td>', 'Good post-processing: half photo, half watercolor. Nicely contrasted and saturated, too.', '2006-05-08 15:01:39.000000', NULL, 1),
(2393793, 330771, 10985, '<td valign="top">Intriguing image, very good for a movie poster.</td>', 'Intriguing image, very good for a movie poster.', '2006-05-08 15:02:40.000000', NULL, 1),
(2393796, 331171, 10985, '<td valign="top">Effective, well titled and... thos greens!</td>', 'Effective, well titled and... thos greens!', '2006-05-08 15:03:07.000000', NULL, 1),
(2393798, 331388, 10985, '<td valign="top">Maybe a little tight for the fish on the left, but very nice.</td>', 'Maybe a little tight for the fish on the left, but very nice.', '2006-05-08 15:03:56.000000', NULL, 1),
(2393801, 331158, 42100, '<td valign="top">I like the how the blur sets the subject off, but still seems a little busy compositionally.</td>', 'I like the how the blur sets the subject off, but still seems a little busy compositionally.', '2006-05-08 15:05:57.000000', NULL, 1),
