(2394748, 331194, 27901, '<td valign="top">Great title and great picture;-)</td>', 'Great title and great picture;-)', '2006-05-08 20:13:13.000000', NULL, 1),
(2394750, 330592, 46782, '<td valign="top">Love it</td>', 'Love it', '2006-05-08 20:13:29.000000', NULL, 1),
(2394752, 331066, 46782, '<td valign="top">Nice work.</td>', 'Nice work.', '2006-05-08 20:13:58.000000', NULL, 1),
