(2401820, 331458, 4517, '<td valign="top">Good colour and background.Nice pic.</td>', 'Good colour and background.Nice pic.', '2006-05-10 15:12:38.000000', NULL, 1),
(2401830, 331319, 4517, '<td valign="top">A photo that actually looks like a poster.Bonus points.9</td>', 'A photo that actually looks like a poster.Bonus points.9', '2006-05-10 15:14:55.000000', NULL, 1),
(2401851, 328792, 4517, '<td valign="top">I think we have a winner here.Excellent 10.</td>', 'I think we have a winner here.Excellent 10.', '2006-05-10 15:18:03.000000', NULL, 1),
(2401861, 330620, 4517, '<td valign="top">Very clever, one of only a few that look like posters.</td>', 'Very clever, one of only a few that look like posters.', '2006-05-10 15:19:45.000000', NULL, 1),
